import test from 'node:test';import assert from 'node:assert/strict';
import * as H from '../content/tech/ch06.shared.js';import a from '../content/tech/ch06.js';import b from '../content/tech/ch06-b.js';import sy from '../content/tech/syllabus.js';
const BASELINE={"collection":"tech","chapters":[{"n":1,"title":"Prehistoric foundations","summary":"The oldest technologies are older than our species: flaked stone, controlled fire, and later the spear-thrower and bow, which store and release mechanical energy. Clothing, pottery and weaving followed, and the domestication of plants and animals changed what people could build and how many could live together. Every later chapter rests on these.","items":[{"num":"1.1","kind":"Invention","name":"Oldowan stone tools: conchoidal fracture","deps":[],"refs":["Cardwell"],"tags":["prehistory","c. 2.6 mya"],"pic":"Strike a virtual flint core at an adjustable angle and force: a cone of fracture propagates and a sharp flake comes off only within a narrow window of striking angles."},{"num":"1.2","kind":"Invention","name":"The Acheulean hand axe","deps":["tech-1.1"],"refs":["Cardwell"],"tags":["prehistory","c. 1.7 mya"],"pic":"Shape a biface by choosing flake removals on both faces: symmetry and edge length are scored, and the cutting edge per kilogram of stone is compared with an Oldowan chopper."},{"num":"1.3","kind":"Invention","name":"Control of fire","deps":[],"refs":["Cardwell"],"tags":["prehistory"],"pic":"Fire triangle sliders (fuel, oxygen, heat): a hearth stays lit only inside the region where heat release exceeds losses, with cooking’s energy gain from food shown alongside."},{"num":"1.4","kind":"Invention","name":"The spear-thrower (atlatl)","deps":["tech-1.2","mech-2.8"],"refs":["Cardwell"],"tags":["prehistory"],"pic":"Launch a dart by hand and with an atlatl of adjustable length: the extra lever arm raises release speed and range, computed from the arm’s rotation rate."},{"num":"1.5","kind":"Invention","name":"The bow and arrow","deps":["tech-1.4","mech-4.1","mech-3.1"],"refs":["Cardwell"],"tags":["prehistory"],"pic":"Draw a bow: the force–draw curve is plotted, the stored energy is the area under it, and arrow speed follows from the fraction transferred."},{"num":"1.6","kind":"Invention","name":"The eyed needle and sewn clothing","deps":["tech-1.2"],"refs":["Cardwell"],"tags":["prehistory","c. 40 kya"],"pic":"Compare heat loss from a body in still air, a draped hide and fitted sewn layers, with trapped-air insulation computed for each."},{"num":"1.7","kind":"Invention","name":"Pottery","deps":["tech-1.3"],"refs":["Cardwell"],"tags":["prehistory","c. 20 kya"],"pic":"Fire clay at increasing kiln temperatures: water loss, sintering and vitrification stages are marked, and only fired pots survive the soaking test."},{"num":"1.8","kind":"Event","name":"Domestication of plants and animals","deps":["tech-1.2"],"refs":["Cardwell"],"tags":["prehistory","c. 10,000 BCE"],"pic":"Select wild wheat for non-shattering seed heads generation by generation: the domestic trait spreads at a rate set by the harvest method."},{"num":"1.9","kind":"Invention","name":"Spinning and the loom","deps":["tech-1.6","tech-1.8"],"refs":["Usher, “Textile machinery”"],"tags":["prehistory"],"pic":"Twist fibres into yarn with a drop spindle and interlace warp and weft on a warp-weighted loom: weave patterns are generated from the lifting sequence."}]},{"n":2,"title":"Simple machines and the ancient engineers","summary":"The lever, wheel and axle, pulley, inclined plane, wedge and screw trade force for distance without creating work, a principle Greek mechanics made exact. Combined with gears and cranks they gave the ancient world water lifts, calculating devices like the Antikythera mechanism, and machines of war.","items":[{"num":"2.1","kind":"Law","name":"The law of the lever (Archimedes)","deps":["mech-2.8"],"refs":["Mokyr ch. 2"],"tags":["ancient"],"pic":"Place weights on a balance beam at draggable distances: it balances when the moments are equal, with the torque bars shown on either side."},{"num":"2.2","kind":"Invention","name":"The wheel and axle","deps":["tech-2.1"],"refs":["Mokyr ch. 2"],"tags":["ancient","c. 3500 BCE"],"pic":"Drag a load on a sledge and on a cart: rolling replaces sliding friction with a much smaller axle friction, and the pulling force is compared."},{"num":"2.3","kind":"Invention","name":"The inclined plane and the wedge","deps":["mech-3.1","mech-1.15"],"refs":["Mokyr ch. 2"],"tags":["ancient"],"pic":"Push a block up ramps of adjustable slope with and without friction: force falls as the path lengthens, while work done (force × distance) stays fixed in the frictionless case."},{"num":"2.4","kind":"Invention","name":"The screw","deps":["tech-2.3"],"refs":["Mokyr ch. 2"],"tags":["ancient"],"pic":"Unroll a screw thread into an inclined plane: pitch and handle radius set the mechanical advantage of a press, read out live."},{"num":"2.5","kind":"Invention","name":"Pulleys and the block and tackle","deps":["tech-2.1","mech-1.14"],"refs":["Mokyr ch. 2"],"tags":["ancient"],"pic":"Add pulleys to a tackle: the rope tension needed falls as 1/n while the rope pulled grows as n, with each segment’s tension labelled."},{"num":"2.6","kind":"Principle","name":"Mechanical advantage and conservation of work","deps":["tech-2.1","tech-2.3","tech-2.5","mech-3.2"],"refs":["Mokyr ch. 2"],"tags":["ancient"],"pic":"Chain simple machines into a compound machine: total advantage is the product of each stage, and a work meter shows input equals output plus friction losses."},{"num":"2.7","kind":"Invention","name":"The shadoof","deps":["tech-2.1"],"refs":["Mokyr ch. 2"],"tags":["ancient","c. 2000 BCE"],"pic":"A counterweighted lever lifts water from a river: choose the counterweight and see the effort on the way down and up balance over a cycle."},{"num":"2.8","kind":"Invention","name":"Archimedes’ screw","deps":["tech-2.4"],"refs":["Mokyr ch. 2"],"tags":["ancient","c. 250 BCE"],"pic":"Turn an inclined helical tube: pockets of water are trapped and carried upward each turn; tilt it too steeply and the pockets spill back."},{"num":"2.9","kind":"Invention","name":"Gear trains and the Antikythera mechanism","deps":["tech-2.2"],"refs":["Mokyr ch. 2"],"tags":["ancient","c. 100 BCE"],"pic":"Mesh gears with chosen tooth counts: the output turns at the product of ratios, and a reconstructed train reproduces the 19-year Metonic cycle."},{"num":"2.10","kind":"Invention","name":"The crank and connecting rod","deps":["tech-2.2"],"refs":["Mokyr ch. 2"],"tags":["ancient","c. 250 CE"],"pic":"Convert rotation to reciprocation as in the Hierapolis sawmill: piston position versus crank angle is plotted and departs from a pure sine for a short rod."},{"num":"2.11","kind":"Invention","name":"The counterweight trebuchet","deps":["tech-2.1","mech-3.6"],"refs":["Mokyr ch. 3"],"tags":["medieval"],"pic":"Drop a counterweight that swings a sling-armed beam: potential energy turns into projectile speed, and the release angle sets range and efficiency."}]},{"n":3,"title":"Materials, writing and number","summary":"Kilns hot enough for pottery made metallurgy possible: copper, then bronze, then iron and steel. The first cities kept records on clay, and writing in turn enabled accounting, law and literature, while paper made writing cheap. Counting boards and the abacus, and later place-value numerals with zero, made arithmetic mechanical.","items":[{"num":"3.1","kind":"Invention","name":"Copper smelting","deps":["tech-1.7","tech-1.3"],"refs":["Mokyr ch. 2"],"tags":["ancient","c. 5000 BCE"],"pic":"Raise furnace temperature and add charcoal: copper ore reduces to metal only above about 1100 °C with enough carbon monoxide, shown on a temperature–atmosphere chart."},{"num":"3.2","kind":"Invention","name":"Bronze","deps":["tech-3.1"],"refs":["Mokyr ch. 2"],"tags":["ancient","c. 3300 BCE"],"pic":"Mix tin into copper with a slider: hardness rises and the melting point falls, with tools of each alloy compared for edge retention."},{"num":"3.3","kind":"Invention","name":"Iron and the bloomery","deps":["tech-3.1"],"refs":["Mokyr ch. 2"],"tags":["ancient","c. 1200 BCE"],"pic":"A bloomery furnace never melts iron: a spongy bloom forms below the melting point and must be hammered to expel slag, step by step."},{"num":"3.4","kind":"Invention","name":"Steel: carburising and quenching","deps":["tech-3.3","mat-6.6"],"refs":["Mokyr ch. 2"],"tags":["ancient"],"pic":"Choose carbon content and cooling rate: the iron–carbon diagram and the resulting hardness and brittleness of the blade update."},{"num":"3.5","kind":"Invention","name":"Glass","deps":["tech-1.7","mat-8.9"],"refs":["Mokyr ch. 2"],"tags":["ancient","c. 2500 BCE"],"pic":"Melt sand with soda and lime: the flux lowers the working temperature, and the viscosity curve shows the window for glassblowing."},{"num":"3.6","kind":"Invention","name":"Writing (Mesopotamia and Egypt)","deps":["ling-7.2","ling-7.3","tech-1.7"],"refs":["Mokyr ch. 2"],"tags":["ancient","c. 3200 BCE"],"pic":"Impress a stylus into clay to write a grain receipt: signs for numbers and commodities combine, and later signs are reused for sounds by the rebus principle."},{"num":"3.7","kind":"Invention","name":"Paper","deps":["tech-3.6","tech-1.9"],"refs":["Mokyr ch. 3"],"tags":["ancient","c. 100 CE"],"pic":"Beat plant fibre into pulp, form a sheet on a screen and press it: cost per page is compared with papyrus and parchment at each step."},{"num":"3.8","kind":"Invention","name":"Counting boards and the abacus","deps":["tech-3.6"],"refs":["Mokyr ch. 2"],"tags":["ancient"],"pic":"Add and multiply on a suanpan: beads carry from column to column, and the same sums are traced on a Roman counting board."},{"num":"3.9","kind":"Invention","name":"Place-value numerals with zero","deps":["tech-3.8"],"refs":["Mokyr ch. 3"],"tags":["medieval","c. 600 CE"],"pic":"Multiply two numbers in Roman numerals and in Hindu–Arabic numerals side by side: the place-value algorithm takes far fewer symbol operations, counted live."},{"num":"3.10","kind":"Invention","name":"The balance and standard weights","deps":["tech-2.1"],"refs":["Mokyr ch. 2"],"tags":["ancient"],"pic":"Weigh goods on an equal-arm balance and a steelyard: the steelyard’s sliding counterpoise uses the lever law to weigh heavy loads with a light weight."}]},{"n":4,"title":"Building, water and power before steam","summary":"Roman engineers combined the arch and hydraulic concrete into aqueducts, bridges and domes. Water wheels and windmills, spreading through medieval Europe, were the first prime movers that did not eat, and with cams and cranks they drove hammers, saws and bellows. Agriculture changed too, with the heavy plough and the horse collar, and canals lifted boats with pound locks.","items":[{"num":"4.1","kind":"Invention","name":"The true arch in Roman engineering","deps":["arch-3.2","arch-3.5"],"refs":["Vitruvius VI.8.3–4; Huerta2009 pp.842–843"],"tags":["ancient"],"pic":"Compare finite radial-contact equilibrium and capped equal-block stacks; distinguish joint admissibility from continuous or real-structure safety."},{"num":"4.2","kind":"Invention","name":"Roman concrete (pozzolana)","deps":["tech-1.7"],"refs":["Vitruvius II.5/II.6/V.12; Jackson 2013; Seymour 2023"],"tags":["ancient"],"pic":"Separate sand and volcanic-powder recipes from an explicit 60-cell conversion proxy whose average matches the plotted model."},{"num":"4.3","kind":"Invention","name":"Aqueducts and the inverted siphon","deps":["fluid-2.2"],"refs":["Vitruvius VIII.6, channel fall and venter; MIT 1.060 Lecture 16"],"tags":["ancient"],"pic":"Fixed tank heights, full pipe length and finite pressure profile distinguish hydraulic capacity from requested flow, arrival height and material failure."},{"num":"4.4","kind":"Invention","name":"The water wheel","deps":["tech-2.2","tech-2.9"],"refs":["Vitruvius X.5; Smeaton 1759 Parts I–II"],"tags":["ancient"],"pic":"Compare explicit authored hydraulic rules over the full speed domain; inspect a normalized wheel whose phase uses its physical radius."},{"num":"4.5","kind":"Event","name":"Smeaton’s water-wheel experiments","deps":["tech-4.4","mech-3.6"],"refs":["Smeaton 1759, Tables I–II pp.115/129"],"tags":["industrial","1759"],"pic":"Replay all 43 printed sets with explicit power bases and a separate plot of rounding and internal arithmetic discrepancies."},{"num":"4.6","kind":"Invention","name":"The windmill","deps":["tech-4.4","energy-5.2"],"refs":["National Trust Pitstone; Jonkman 2003 §2.2"],"tags":["wind","prime mover"],"pic":"Separate an ideal aligned actuator-disc coefficient from a declared alignment estimate; show complete induction and wind-speed families."},{"num":"4.7","kind":"Invention","name":"The cam and the trip hammer","deps":["tech-4.4","mech-3.1"],"refs":["Agricola 1556, Book VIII / Hoover 1912 pp.280–287"],"tags":["mechanism"],"pic":"Inspect one exact constrained lift and isolated gravity fall, including guide-force feasibility and the next scheduled lug deadline."},{"num":"4.8","kind":"Invention","name":"The heavy plough and the horse collar","deps":["tech-1.8","tech-3.3","arch-1.2"],"refs":["F. Inns, FAO Matching tillage implements to draught animal potential"],"tags":["medieval"],"pic":"Resolve trace tension into horizontal and vertical components; include the same angle in conditional team demand."},{"num":"4.9","kind":"Invention","name":"The stirrup","deps":["mech-2.1","mech-2.6"],"refs":["Bayarsaikhan et al. Antiquity2024 DOI10.15184/aqy.2023.172"],"tags":["medieval"],"pic":"Separate archaeological dating qualifications from an exact sequential capture-and-coupling momentum model."},{"num":"4.10","kind":"Invention","name":"The canal pound lock","deps":["tech-4.3","fluid-2.10"],"refs":["Canal & River Trust handbook and lockage definition"],"tags":["canals"],"pic":"Follow a chamber level change and account separately for upper withdrawal, lower delivery and storage, with gates ready only at matching levels."},{"num":"4.11","kind":"Invention","name":"Sternpost rudder and lateen sail","deps":["aero-1.2","aero-1.3"],"refs":["Whitewright 2011, IJNA 40.1:2–17, DOI 10.1111/j.1095-9270.2010.00276.x; RMG model SLR2362, unknown date"],"tags":["ships"],"pic":"Separate historical performance evidence from an authored finite-trim force model; rotate actual one-metre blades and compare signed tip depths."},{"num":"4.12","kind":"Paper","name":"The Natural Powers of Water and Wind to Turn Mills","paper":{"authors":"John Smeaton","year":1759,"title":"An Experimental Enquiry Concerning the Natural Powers of Water and Wind to Turn Mills, and Other Machines, Depending on a Circular Motion","venue":"Philosophical Transactions of the Royal Society of London 51: 100–174","doi":"10.1098/rstl.1759.0019"},"introduces":["tech-4.5"],"deps":["tech-4.4","tech-4.6"],"refs":["Smeaton 1759 Table III p.144 and six-station footnote p.148"],"pic":"Compare all 19 printed sail products with cloth area retained, and inspect the separate six full-size trial stations in either angle convention."}]},{"n":5,"title":"Time and navigation","summary":"Water clocks and sundials kept time imperfectly until the mechanical escapement, around 1300, turned a falling weight into steady ticks. Galileo’s and Huygens’ pendulum made clocks accurate, and the balance spring did the same for portable watches. That precision solved the longitude problem at sea, alongside the compass, astrolabe and sextant.","items":[{"num":"5.1","kind":"Invention","name":"The water clock (clepsydra)","deps":["fluid-2.10"],"refs":["NMEC JE 37525; WCO 1 catalogue; Vitruvius IX.8"],"tags":["ancient"],"pic":"Exact ideal outflow separates an equal-level scale from a supplied constant-head source and its separate rising receiver."},{"num":"5.2","kind":"Invention","name":"The astrolabe","deps":["geog-5.2"],"refs":["RMG AST0558 actual owner record, separated-parts image and condition account"],"tags":["astronomy","projection"],"pic":"Turn an ideal rete over a finite stereographic plate whose altitude circles end exactly at the rim. Authored celestial coordinates and a declared circular-orbit Sun replace unsupported historical star positions and calendar precision; the full altitude cycle agrees with the selected point."},{"num":"5.3","kind":"Invention","name":"The magnetic compass","deps":["em-7.18","mech-4.7"],"refs":["RMG RAF Mark II ACO0299 actual needle/float/damping-vane and condition account"],"tags":["magnetism","navigation"],"pic":"Explore a declared tilted dipole and a nonlinear damped needle with checked energy dissipation. Both axis-pole bearings are explicitly undefined; exact saved observer coordinates, real dragging and full trajectory bounds agree without claiming a current magnetic map or calibrated historical dynamics."},{"num":"5.4","kind":"Invention","name":"Mechanical clock with verge-and-foliot escapement","deps":["tech-2.9","mech-4.7"],"refs":["Hoyng and Nieuwenhuizen, arXiv:1604.06681v2, §II and Appendix A"],"tags":["timekeeping","mechanism"],"pic":"Examine the stationary threshold-switched, viscously damped foliot: drive, friction, inertia and switch angle determine period and overshoot. Exact turning points, model work and actual phase controls share the analytic solution."},{"num":"5.5","kind":"Invention","name":"The mainspring and fusee","deps":["tech-2.9","mech-4.1"],"refs":["GNM HG9771 owner record; Eser 2014, actual sample pp.6–7 and26–29"],"tags":["timekeeping","mechanism"],"pic":"Compare a compensating fusee with a plain drum under one torque normalization. The declared spring law, all 501 curve samples and selected working radius agree; historical objects do not calibrate this authored model."},{"num":"5.6","kind":"Invention","name":"The pendulum clock (Huygens)","deps":["mech-4.4","mech-5.8"],"refs":["Huygens 1673 original ETH Rar4649, PartI construction; PartII PropXXV57–58; PartIII PropsV–VII66–68"],"tags":["pendulum","cycloid","timekeeping"],"pic":"Compare exact nonlinear circular motion with the isochronous cycloid at equal release energy. The actual wrapped cheek arc and free string sum to one metre; full circular-error curves and exact elapsed-time controls share the physical model."},{"num":"5.7","kind":"Invention","name":"The anchor escapement","deps":["tech-5.6","mech-4.4"],"refs":["Metropolitan Museum of Art, Knibb clock1974.28.92, actual movement and condition account"],"tags":["timekeeping","escapement"],"pic":"Compare exact ideal pendulum circular error and finite ±10% amplitude bands without flooring small errors. A separate enlarged rocker schematic makes no tooth-contact, recoil, historical-priority or measured-accuracy claim."},{"num":"5.8","kind":"Invention","name":"The balance spring","deps":["mech-4.2","mech-4.1"],"refs":["Metropolitan Museum of Art, Van Ceulen watch17.190.1417, actual movement and condition account"],"tags":["timekeeping","spring","oscillator"],"pic":"Compare exact linear and hardening-spring trajectories and complete period curves under an explicit270° reference calibration. Elliptic motion conserves the declared quartic energy; symbolic spirals and historical object evidence do not calibrate a real watch."},{"num":"5.9","kind":"Concept","name":"The longitude problem","deps":["tech-5.6","geog-2.4"],"refs":["Longitude Act1714, actual Cambridge RGO14/1 fols.11r–12r, printed355–357"],"tags":["navigation","time"],"pic":"Compare one signed affine clock-error model across the map, full90-day curve and selected day. Exact zero crossings and parallel arcs are explicit; angular benchmarks alone do not establish eligibility under the Act."},{"num":"5.10","kind":"Invention","name":"Harrison’s marine chronometer","deps":["tech-5.8","tech-5.9"],"refs":["Royal Museums Greenwich, H4 ZAA0037 owner record and actual inscription"],"tags":["timekeeping","navigation"],"pic":"Separate H4 artifact evidence from three authored uncalibrated sensitivity profiles. All daily trajectories, exact discrete systematic mean and independent-increment RMS share a registered replayable seed and complete signed plot bounds."},{"num":"5.11","kind":"Invention","name":"The octant and sextant","deps":["waves-4.5","geog-2.4"],"refs":["Hadley1731 actual original147–157 and plates; Whipple Museum Troughton sextant1295"],"tags":["navigation","optics"],"pic":"Trace two exact ideal reflections and compare the allowed mirror angle with its doubled reading. Separate general object angles from visible noon altitudes; the noon interpretation retains both valid latitude branches instead of silently assuming the Sun is south."}]},{"n":6,"title":"Lenses, printing and gunpowder","summary":"Ground glass lenses gave old eyes their sight back and, combined in tubes, revealed moons of Jupiter and microbes. Movable type, oil-based ink, paper and the screw press combined into Gutenberg’s printing system, which made books cheap enough to change how knowledge spread. Gunpowder reshaped warfare, and the barometer and air pump revealed the atmospheric pressure the steam engine would exploit.","items":[{"num":"6.1","kind":"Invention","name":"Spectacles","deps":["tech-3.5","art-2.5","waves-5.6"],"refs":["Mokyr ch. 3"],"tags":["medieval","c. 1286"],"pic":"Model a presbyopic eye focusing on a page: the near point recedes with age, and a convex lens of the right power brings the image back onto the retina."},{"num":"6.2","kind":"Invention","name":"Woodblock printing","deps":["tech-3.7"],"refs":["Usher, “The invention of printing”"],"tags":["ancient","c. 700 CE"],"pic":"Carve a mirror-image block and print: compare carving time per page with copying by hand as the print run grows."},{"num":"6.3","kind":"Invention","name":"Movable type in East Asia","deps":["tech-6.2"],"refs":["Usher, “The invention of printing”"],"tags":["medieval","c. 1040"],"pic":"Typeset a page from a case of reusable characters: the number of distinct sorts needed for Chinese versus an alphabet is shown as a growth curve."},{"num":"6.4","kind":"Invention","name":"Gutenberg’s printing press","deps":["tech-6.3","tech-2.4","tech-3.7","ling-7.4"],"refs":["Usher, “The invention of printing”","Mokyr ch. 3"],"tags":["early-modern","c. 1450"],"pic":"Step through the system: cast type in a hand mould, compose, ink with oil-based ink, and press with a screw; pages per hour and cost per book are tracked."},{"num":"6.5","kind":"Event","name":"The printing revolution","deps":["tech-6.4"],"refs":["Mokyr ch. 4"],"tags":["early-modern"],"pic":"Book output in Europe on a log scale before and after 1450 with book prices falling: drag the start date to see the curve bend at Gutenberg."},{"num":"6.6","kind":"Invention","name":"The telescope","deps":["tech-6.1"],"refs":["Mokyr ch. 4"],"tags":["early-modern","1608"],"pic":"Combine a weak convex objective and a strong eyepiece: magnification is the ratio of focal lengths, and the moons of Jupiter appear as you raise it."},{"num":"6.7","kind":"Invention","name":"The microscope","deps":["tech-6.1"],"refs":["Mokyr ch. 4"],"tags":["early-modern","c. 1620"],"pic":"Compare a compound microscope of the 1600s with van Leeuwenhoek’s tiny single lens: magnification and aberrations are computed, and his lens wins on resolution."},{"num":"6.8","kind":"Invention","name":"The reflecting telescope and the achromat","deps":["tech-6.6","art-3.1"],"refs":["Mokyr ch. 4"],"tags":["early-modern","1668"],"pic":"White starlight through a single lens splits into coloured foci; switch to a mirror (Newton) or a crown–flint doublet (Dollond) and the foci merge."},{"num":"6.9","kind":"Invention","name":"Gunpowder","deps":["tech-1.3"],"refs":["Mokyr ch. 3"],"tags":["medieval","c. 850"],"pic":"Vary the proportions of saltpetre, charcoal and sulphur: burn rate and gas volume peak near the classic 75:15:10 mix."},{"num":"6.10","kind":"Invention","name":"Cannon and firearms","deps":["tech-6.9","tech-3.3"],"refs":["Mokyr ch. 3"],"tags":["medieval","c. 1300"],"pic":"Fire a ball from barrels of different length: gas pressure acting along the bore sets muzzle velocity, and the trajectory is integrated with drag."},{"num":"6.11","kind":"Invention","name":"The barometer and the air pump","deps":["tech-3.5"],"refs":["Mokyr ch. 4"],"tags":["early-modern","1643"],"pic":"Invert a mercury tube: the column stops at about 76 cm whatever its length; pump air from Magdeburg hemispheres and the force needed to separate them grows with area."},{"num":"6.12","kind":"Paper","name":"The Printing Press as an Agent of Change","paper":{"authors":"Elizabeth L. Eisenstein","year":1979,"title":"The Printing Press as an Agent of Change: Communications and Cultural Transformations in Early-Modern Europe","venue":"Cambridge: Cambridge University Press, 1979 (2 vols.)","doi":"10.1017/CBO9781107049963"},"introduces":["tech-6.5"],"deps":["tech-6.4"],"refs":[],"pic":"Eisenstein’s effects of print made measurable: the reader follows a text through generations of hand copying, where errors accumulate and copies drift apart, and through printed editions, where identical copies spread, errata are corrected in later editions and scattered sources can be collated side by side, with the count of surviving editions per decade after 1450 climbing alongside."}]},{"n":7,"title":"Steam, iron and the Industrial Revolution","summary":"The first steam engines used atmospheric pressure to pump water from mines. Watt’s separate condenser cut their fuel use dramatically, and rotary motion and governors put them to work driving factories. Cheap coke-smelted iron, precision boring and machine tools made bigger and better engines possible, while engineers’ indicator diagrams and Carnot’s analysis began the science of heat engines.","items":[{"num":"7.1","kind":"Invention","name":"Savery’s and Papin’s steam devices","deps":["tech-6.11"],"refs":["Mokyr ch. 4"],"tags":["early-modern","1698"],"pic":"Condense steam in a closed vessel: the pressure drop sucks water up, limited to about 10 m by the atmosphere; Papin’s cylinder raises a weight with a piston."},{"num":"7.2","kind":"Invention","name":"The Newcomen atmospheric engine","deps":["tech-7.1","tech-2.1"],"refs":["Mokyr ch. 4","Cardwell"],"tags":["early-modern","1712"],"pic":"Cycle a Newcomen engine: steam fills the cylinder, a cold jet condenses it, and atmospheric pressure drives the piston down to rock the beam and pump; heat wasted reheating the cylinder is tallied."},{"num":"7.3","kind":"Invention","name":"Coke smelting of iron (Darby)","deps":["tech-3.3"],"refs":["Mokyr ch. 5"],"tags":["industrial","1709"],"pic":"Replace charcoal with coke in a blast furnace: fuel cost per tonne and the forest area saved are computed, and furnace size can grow."},{"num":"7.4","kind":"Invention","name":"The cylinder-boring machine (Wilkinson)","deps":["tech-7.3"],"refs":["Usher, “Machine tools and quantity production”"],"tags":["industrial","1774"],"pic":"Bore a cylinder with the cutter supported at both ends: the out-of-roundness falls from a shilling’s thickness to a fraction of it, and steam leakage past the piston drops accordingly."},{"num":"7.5","kind":"Invention","name":"Watt’s separate condenser","deps":["tech-7.2","tech-7.4"],"refs":["Mokyr ch. 5","Cardwell"],"tags":["industrial","1769"],"pic":"Toggle between condensing in the cylinder and in a separate cold vessel: the cylinder stays hot, and coal per unit of work falls by roughly two thirds."},{"num":"7.6","kind":"Invention","name":"The rotative engine: sun-and-planet gear and governor","deps":["tech-7.5","tech-2.10","ctrl-1.2"],"refs":["Mokyr ch. 5"],"tags":["industrial","1781"],"pic":"Couple the beam to a flywheel through sun-and-planet gearing, then add the centrifugal governor: under changing mill load the speed drifts less with the governor on."},{"num":"7.7","kind":"Invention","name":"Watt’s parallel motion linkage","deps":["tech-7.6"],"refs":["Mokyr ch. 5"],"tags":["industrial","1784"],"pic":"Animate Watt’s linkage: the coupler midpoint traces a nearly straight line through the stroke, with deviation from straightness plotted."},{"num":"7.8","kind":"Method","name":"The indicator diagram","deps":["tech-7.5","mech-3.1"],"refs":["Cardwell"],"tags":["industrial","c. 1796"],"pic":"Trace pressure against piston position over a cycle: the enclosed area is the work per stroke, and changing cut-off reshapes the loop."},{"num":"7.9","kind":"Invention","name":"High-pressure steam (Trevithick, Evans)","deps":["tech-7.5","tech-3.4"],"refs":["Mokyr ch. 5"],"tags":["industrial","1800"],"pic":"Raise boiler pressure: engine size per horsepower shrinks enough to move on wheels, while boiler-wall stress rises toward the bursting limit."},{"num":"7.10","kind":"Concept","name":"Carnot’s analysis of heat engines","deps":["tech-7.8","thermo-2.7"],"refs":["Cardwell"],"tags":["industrial","1824"],"pic":"Run an ideal engine between a hot and a cold reservoir: its efficiency 1 − T_c/T_h is compared with real engines from Newcomen to modern turbines on one chart."},{"num":"7.11","kind":"Invention","name":"Puddling and rolling (Cort)","deps":["tech-7.3"],"refs":["Mokyr ch. 5"],"tags":["industrial","1784"],"pic":"Stir molten pig iron in a reverberatory furnace to burn off carbon, then pass it through grooved rolls: output per worker is compared with hammering."},{"num":"7.12","kind":"Invention","name":"The Bessemer converter","deps":["tech-7.11"],"refs":["Mokyr ch. 6"],"tags":["industrial","1856"],"pic":"Blow air through molten iron: carbon content falls over minutes while the heat of oxidation keeps the bath molten; the price of steel drops on a timeline."},{"num":"7.13","kind":"Invention","name":"The screw-cutting lathe and standard threads","deps":["tech-7.4","tech-2.4"],"refs":["Usher, “Machine tools and quantity production”"],"tags":["industrial","c. 1800"],"pic":"Gear a lathe’s lead screw to the spindle: change gears to cut any pitch, and the thread error is copied from the lead screw onto the work."},{"num":"7.14","kind":"Invention","name":"Interchangeable parts","deps":["tech-7.13"],"refs":["Usher, “Machine tools and quantity production”"],"tags":["industrial"],"pic":"Assemble muskets from random parts made to tolerances of different widths: the fraction that fit without filing rises sharply as tolerances tighten."}]},{"n":8,"title":"Textiles, railways and steamships","summary":"Cotton was the first industry to be mechanised: the flying shuttle sped weaving, which created demand for yarn that the jenny, water frame and mule supplied, until the power loom caught up. Jacquard’s punched cards programmed a loom. Applied to transport, high-pressure steam produced the locomotive and the steamship, which shrank distances and imposed standard time.","items":[{"num":"8.1","kind":"Invention","name":"The flying shuttle (Kay)","deps":["tech-1.9"],"refs":["Usher, “Textile machinery”","Mokyr ch. 5"],"tags":["industrial","1733"],"pic":"Weave by passing the shuttle by hand and by striking it with a picker: cloth width and picks per minute both increase, unbalancing yarn supply."},{"num":"8.2","kind":"Invention","name":"The spinning jenny (Hargreaves)","deps":["tech-1.9","tech-8.1"],"refs":["Usher, “Textile machinery”","Mokyr ch. 5"],"tags":["industrial","c. 1765"],"pic":"One wheel drives many spindles: drawing and twisting happen in a single carriage stroke, and output per spinner scales with spindle count."},{"num":"8.3","kind":"Invention","name":"The water frame and the factory (Arkwright)","deps":["tech-8.2","tech-4.4"],"refs":["Usher, “Textile machinery”","Mokyr ch. 5"],"tags":["industrial","1769"],"pic":"Successive pairs of rollers turning at increasing speeds draw out the roving before twisting: the draft ratio sets yarn fineness, all powered from one water wheel."},{"num":"8.4","kind":"Invention","name":"The spinning mule (Crompton)","deps":["tech-8.2","tech-8.3"],"refs":["Usher, “Textile machinery”","Mokyr ch. 5"],"tags":["industrial","1779"],"pic":"Combine roller drafting with the jenny’s moving carriage: yarn strength and fineness exceed both parents, shown on a fineness–strength chart."},{"num":"8.5","kind":"Invention","name":"The power loom (Cartwright)","deps":["tech-8.1","tech-7.6"],"refs":["Usher, “Textile machinery”","Mokyr ch. 5"],"tags":["industrial","1785"],"pic":"A cam-driven loom cycles shedding, picking and beating up: its timing diagram runs, and a handloom weaver’s wage curve falls as power looms spread."},{"num":"8.6","kind":"Invention","name":"The Jacquard loom: punched-card control","deps":["tech-8.5"],"refs":["Usher, “Textile machinery”","Mokyr ch. 5"],"tags":["industrial","1804"],"pic":"Punch a chain of cards and the loom lifts exactly the warp threads with holes: the woven pattern is generated row by row from the program."},{"num":"8.7","kind":"Invention","name":"The cotton gin (Whitney)","deps":[],"refs":["Mokyr ch. 5"],"tags":["industrial","1793"],"pic":"Wire teeth on a drum pull fibre through a grate too narrow for seeds: pounds of cleaned cotton per day by hand and by gin are compared."},{"num":"8.8","kind":"Invention","name":"The steam locomotive (Stephenson’s Rocket)","deps":["tech-7.9","tech-7.11"],"refs":["Mokyr ch. 5"],"tags":["industrial","1829"],"pic":"Fire-tube boiler and blast pipe: exhaust steam drafts the fire harder as speed rises, so steam production keeps pace; tractive effort and speed are plotted."},{"num":"8.9","kind":"Event","name":"Railway networks and standard time","deps":["tech-8.8","tech-5.10"],"refs":["Mokyr ch. 6"],"tags":["industrial","1840s"],"pic":"Towns along a line keep local solar time differing by minutes: timetables become inconsistent until a single railway time is imposed, animated on a map."},{"num":"8.10","kind":"Invention","name":"The steamship and the screw propeller","deps":["tech-7.9","tech-2.8"],"refs":["Mokyr ch. 6"],"tags":["industrial","1840s"],"pic":"Paddle versus screw in a tug-of-war, as in the 1845 Rattler–Alecto trial: thrust per horsepower is computed, and Atlantic crossing times fall on a timeline."}]},{"n":9,"title":"Electricity: telegraph, telephone and power","summary":"Batteries gave steady currents, electromagnets turned currents into force, and the telegraph turned both into instant long-distance messages coded in dots and dashes. Faraday’s induction led to dynamos and motors, and Edison’s lamps needed central power stations and wires. The battle of the currents was won by alternating current because transformers make high-voltage transmission efficient.","items":[{"num":"9.1","kind":"Invention","name":"The Leyden jar","deps":["tech-3.5","em-1.3"],"refs":["Mokyr ch. 4"],"tags":["early-modern","1745"],"pic":"Charge a glass jar with foil coatings: stored charge rises with voltage and plate area, and the spark gap discharges it when the field exceeds breakdown."},{"num":"9.2","kind":"Invention","name":"The voltaic pile","deps":["tech-9.1"],"refs":["Mokyr ch. 5"],"tags":["industrial","1800"],"pic":"Stack zinc–brine–copper cells: voltage adds in series while internal resistance limits the current, plotted as a load line."},{"num":"9.3","kind":"Invention","name":"The electromagnet","deps":["tech-9.2","em-10.2"],"refs":["Mokyr ch. 6"],"tags":["industrial","1825"],"pic":"Wind turns of wire around an iron core: field strength grows with ampere-turns until the core saturates, lifting more weight on screen."},{"num":"9.4","kind":"Invention","name":"The electric telegraph","deps":["tech-9.2","tech-9.3"],"refs":["Mokyr ch. 6"],"tags":["industrial","1837"],"pic":"Key a message on a line with relays: the far sounder clicks in step, and a relay restores a signal weakened by line resistance."},{"num":"9.5","kind":"Invention","name":"Morse code","deps":["tech-9.4","ling-4.7"],"refs":["Mokyr ch. 6"],"tags":["industrial","1844"],"pic":"Type text and see it keyed in Morse: average code length per letter is compared with a fixed-length code and with an optimal Huffman code built from English letter frequencies."},{"num":"9.6","kind":"Invention","name":"The transatlantic telegraph cable","deps":["tech-9.4","circ-9.2"],"refs":["Mokyr ch. 6"],"tags":["industrial","1858–66"],"pic":"Send a pulse down a long cable: it spreads out by diffusion with delay growing as length squared (Kelvin’s law of squares), limiting words per minute."},{"num":"9.7","kind":"Invention","name":"Photography","deps":["art-2.3","art-2.5"],"refs":["Mokyr ch. 6"],"tags":["industrial","1839"],"pic":"Expose a plate in a camera obscura with a lens: exposure time falls from hours (Niépce) to minutes (daguerreotype) to fractions of a second as sensitivity improves."},{"num":"9.8","kind":"Invention","name":"The telephone","deps":["tech-9.3","music-1.1"],"refs":["Mokyr ch. 6"],"tags":["industrial","1876"],"pic":"Sound vibrates a diaphragm that varies a current; at the receiver the current moves another diaphragm, and the transmitted waveform is shown at each stage."},{"num":"9.9","kind":"Invention","name":"The phonograph","deps":["music-1.1"],"refs":["Mokyr ch. 6"],"tags":["industrial","1877"],"pic":"A stylus engraves a groove whose depth follows the sound wave; playback retraces it, and the groove profile is drawn under the waveform."},{"num":"9.10","kind":"Invention","name":"The dynamo and the electric motor","deps":["em-9.3","em-9.11","em-9.21"],"refs":["Mokyr ch. 6"],"tags":["industrial","1831–1870s"],"pic":"Spin a coil in a magnetic field: induced voltage follows the rate of flux change, a commutator rectifies it, and running the machine backward makes it a motor."},{"num":"9.11","kind":"Invention","name":"The incandescent light bulb","deps":["tech-9.10","tech-6.11","circ-1.4"],"refs":["Mokyr ch. 6"],"tags":["industrial","1879"],"pic":"Choose filament material, resistance and vacuum quality: lamp life and light output trade off, and a high-resistance filament suits parallel wiring."},{"num":"9.12","kind":"Invention","name":"Central power stations and distribution","deps":["tech-9.10","tech-9.11"],"refs":["Mokyr ch. 6"],"tags":["industrial","1882"],"pic":"Supply lamps across a district from one station: I²R losses in the wires are computed for each delivery voltage, limiting DC service to a mile or so."},{"num":"9.13","kind":"Event","name":"The war of the currents: AC versus DC","deps":["tech-9.12","em-9.14"],"refs":["Mokyr ch. 6"],"tags":["industrial","1880s"],"pic":"Step voltage up with a transformer, transmit, and step it down: line losses fall with the square of the voltage ratio, deciding the contest."},{"num":"9.14","kind":"Invention","name":"Polyphase AC and the induction motor","deps":["tech-9.13","em-9.21"],"refs":["Mokyr ch. 6"],"tags":["industrial","1888"],"pic":"Three coils fed with phase-shifted currents produce a rotating magnetic field that drags a rotor round, with slip and torque shown live."},{"num":"9.15","kind":"Invention","name":"The steam turbine (Parsons)","deps":["tech-7.9","tech-7.10"],"refs":["Mokyr ch. 6"],"tags":["industrial","1884"],"pic":"Expand steam through successive stages of fixed and moving blades: pressure drops a little at each stage, keeping blade speeds practical, coupled to a generator."}]},{"n":10,"title":"Engines, flight, chemistry and medicine","summary":"Burning fuel inside the cylinder gave lighter, more compact engines than steam, and with them the car and the aeroplane, whose controllability mattered as much as its engine. Jet engines and rockets extended the same principle. Chemistry produced synthetic dyes, plastics and, through the Haber–Bosch process, the nitrogen fertiliser that now feeds billions, while vaccination, germ theory and antibiotics transformed medicine.","items":[{"num":"10.1","kind":"Invention","name":"The four-stroke internal combustion engine (Otto)","deps":["tech-7.8","tech-2.10"],"refs":["Mokyr ch. 6"],"tags":["industrial","1876"],"pic":"Animate intake, compression, power and exhaust strokes with the p–V loop drawn alongside; raise the compression ratio and the ideal Otto efficiency climbs."},{"num":"10.2","kind":"Invention","name":"The Diesel engine","deps":["tech-10.1"],"refs":["Mokyr ch. 6"],"tags":["industrial","1893"],"pic":"Compress air until it is hot enough to ignite injected fuel: the higher compression ratio raises efficiency, compared on the same p–V axes with the Otto cycle."},{"num":"10.3","kind":"Invention","name":"The automobile and the moving assembly line","deps":["tech-10.1","tech-7.14"],"refs":["Cardwell"],"tags":["modern","1885–1913"],"pic":"Assemble a car at fixed stations and on a moving line: chassis assembly time drops from hours to about an hour and a half, as at Ford in 1913–14, and the price curve follows."},{"num":"10.4","kind":"Invention","name":"Gliders and lift measurements","deps":["fluid-5.4"],"refs":["Cardwell"],"tags":["industrial","1890s"],"pic":"Tilt a cambered wing in a virtual wind tunnel: lift rises with angle of attack until stall, and the Wrights’ corrected lift coefficients are plotted beside Lilienthal’s."},{"num":"10.5","kind":"Invention","name":"The aeroplane and three-axis control","deps":["tech-10.1","tech-10.4","fluid-4.11"],"refs":["Cardwell"],"tags":["modern","1903"],"pic":"Fly a simple aircraft model with elevator, rudder and wing-warping controls: without roll control a turn diverges, with it the aircraft banks and turns."},{"num":"10.6","kind":"Invention","name":"The jet engine","deps":["tech-10.5","tech-9.15"],"refs":["Cardwell"],"tags":["modern","1937–39"],"pic":"Compressor, combustor and turbine on one shaft: thrust is mass flow times velocity increase, and efficiency against flight speed is compared with a propeller."},{"num":"10.7","kind":"Invention","name":"The liquid-fuel rocket","deps":["mech-2.7"],"refs":["Cardwell"],"tags":["modern","1926"],"pic":"Burn propellant with an adjustable exhaust velocity and mass ratio: Tsiolkovsky’s equation gives Δv, and staging beats a single stage for orbit."},{"num":"10.8","kind":"Invention","name":"Synthetic dyes and the chemical industry","deps":[],"refs":["Mokyr ch. 6"],"tags":["industrial","1856"],"pic":"Perkin’s mauve from coal tar: the price of purple dye per gram falls by orders of magnitude on a log chart as synthetic dyes replace natural ones."},{"num":"10.9","kind":"Invention","name":"The Haber–Bosch process","deps":["tech-7.9","pchem-7.7"],"refs":["Cardwell"],"tags":["modern","1913"],"pic":"Set temperature and pressure for N₂ + 3H₂ ⇌ 2NH₃: equilibrium yield rises with pressure and falls with temperature while the rate does the opposite, so the compromise near 450 °C and 200 atm is marked."},{"num":"10.10","kind":"Invention","name":"Plastics: Bakelite","deps":["tech-10.8"],"refs":["Cardwell"],"tags":["modern","1907"],"pic":"Phenol and formaldehyde molecules cross-link into a network as the reaction proceeds: once a spanning cluster forms the resin sets and can no longer melt."},{"num":"10.11","kind":"Invention","name":"Vaccination (Jenner)","deps":["mathbio-7.3"],"refs":["Mokyr ch. 5"],"tags":["industrial","1796"],"pic":"Vaccinate a fraction of a simulated population against smallpox: above the herd-immunity threshold 1 − 1/R₀ outbreaks fizzle out."},{"num":"10.12","kind":"Concept","name":"Germ theory and antiseptic surgery","deps":["tech-6.7"],"refs":["Mokyr ch. 6"],"tags":["industrial","1860s"],"pic":"Pasteur’s swan-neck flask stays sterile until tipped; Lister’s carbolic-acid wards show falling surgical mortality in a before-and-after chart."},{"num":"10.13","kind":"Invention","name":"Penicillin and antibiotics","deps":["tech-10.12"],"refs":["Cardwell"],"tags":["modern","1928–43"],"pic":"Bacteria grow on a plate with a mould colony: an inhibition zone appears, and a time-kill curve shows the effect of dose; resistant mutants rise if dosing stops early."},{"num":"10.14","kind":"Invention","name":"Mechanical refrigeration","deps":["tech-7.10","thermo-2.5"],"refs":["Cardwell"],"tags":["industrial","1870s"],"pic":"A vapour-compression cycle: compressor, condenser, expansion valve and evaporator move heat uphill, with the coefficient of performance read out against the temperature lift."}]},{"n":11,"title":"Radio, electronics and computing","summary":"Maxwell predicted electromagnetic waves and Hertz made them; Marconi used them to send messages without wires. The vacuum tube could rectify, amplify and oscillate, which made broadcasting, radar and the first electronic computers possible. The transistor and then the integrated circuit shrank all of this by many orders of magnitude, on the exponential schedule known as Moore’s law, while Turing and von Neumann supplied the logical design of the computer.","items":[{"num":"11.1","kind":"Event","name":"Hertz produces electromagnetic waves","deps":["em-10.3","em-12.7"],"refs":["Mokyr ch. 6"],"tags":["industrial","1887"],"pic":"A spark-gap oscillator and a loop receiver: move the receiver to map standing waves from a reflecting wall and recover the wavelength and speed of the waves."},{"num":"11.2","kind":"Invention","name":"Wireless telegraphy (Marconi)","deps":["tech-11.1","tech-9.5"],"refs":["Cardwell"],"tags":["modern","1895–1901"],"pic":"Raise the antenna and add an earth connection: range grows, and Morse messages crossing the Atlantic are decoded from a noisy received signal."},{"num":"11.3","kind":"Invention","name":"The vacuum diode","deps":["tech-9.11","circ-4.5"],"refs":["Cardwell"],"tags":["modern","1904"],"pic":"Heat a cathode: electrons flow to the anode only when it is positive, and the I–V curve rectifies an AC signal shown on a scope trace."},{"num":"11.4","kind":"Invention","name":"The triode amplifier","deps":["tech-11.3"],"refs":["Cardwell"],"tags":["modern","1906"],"pic":"A small voltage on the grid controls a large anode current: plate characteristics and the gain of a simple amplifier stage are read out."},{"num":"11.5","kind":"Invention","name":"AM broadcasting and the superheterodyne receiver","deps":["tech-11.4","sig-12.3","sig-12.11"],"refs":["Cardwell"],"tags":["modern","1920s"],"pic":"Tune across a crowded band: mixing each station down to a fixed intermediate frequency lets one sharp filter select it, shown in the spectrum."},{"num":"11.6","kind":"Invention","name":"FM radio (Armstrong)","deps":["tech-11.5","sig-12.7"],"refs":["Cardwell"],"tags":["modern","1933"],"pic":"Add noise to AM and FM versions of the same audio: the FM signal recovers cleanly above threshold at the cost of wider bandwidth, both played back."},{"num":"11.7","kind":"Invention","name":"Electronic television","deps":["tech-11.4","tech-9.7"],"refs":["Cardwell"],"tags":["modern","1927"],"pic":"Scan an image line by line into a signal and redraw it on a phosphor screen: lines and frame rate set resolution and bandwidth."},{"num":"11.8","kind":"Invention","name":"Radar and the cavity magnetron","deps":["tech-11.1","tech-11.4","em-12.12"],"refs":["Cardwell"],"tags":["modern","1935–40"],"pic":"Send pulses and time the echoes from aircraft: range is c·t/2, and shorter wavelengths from the magnetron sharpen the beam on the display."},{"num":"11.9","kind":"Invention","name":"Quartz and atomic clocks","deps":["tech-11.4","tech-5.6"],"refs":["Cardwell"],"tags":["modern","1927–55"],"pic":"Allan deviation of a pendulum clock, a quartz oscillator and a caesium clock on a log plot: each step improves stability by orders of magnitude."},{"num":"11.10","kind":"Invention","name":"Mechanical calculators and Babbage’s engines","deps":["tech-3.9","tech-2.9","tech-8.6"],"refs":["Cardwell"],"tags":["industrial","1642–1837"],"pic":"Crank Babbage’s Difference Engine: repeated addition of finite differences tabulates a polynomial with no multiplication, column by column."},{"num":"11.11","kind":"Invention","name":"Punched-card tabulation (Hollerith)","deps":["tech-8.6"],"refs":["Cardwell"],"tags":["industrial","1890"],"pic":"Feed census cards through a reader whose pins close circuits through holes: counters tally categories, and processing time for the census is compared with hand counting."},{"num":"11.12","kind":"Concept","name":"Turing machines and universality","deps":["logic-6.1","toc-7.9"],"refs":["Cardwell"],"tags":["modern","1936"],"pic":"Load a program onto the tape of a universal machine: one fixed machine simulates any other given its description."},{"num":"11.13","kind":"Invention","name":"Switching circuits implement Boolean logic (Shannon)","deps":["logic-2.3"],"refs":["Cardwell"],"tags":["modern","1937"],"pic":"Build an adder from relays in series and parallel: the truth table of each sub-circuit is checked, and binary numbers add live."},{"num":"11.14","kind":"Invention","name":"Electronic computers: Colossus and ENIAC","deps":["tech-11.4","tech-11.13"],"refs":["Cardwell"],"tags":["modern","1943–45"],"pic":"A ballistics table computed by hand, by relay machine and by ENIAC: operations per second on a log axis jump by orders of magnitude with vacuum tubes."},{"num":"11.15","kind":"Concept","name":"The stored-program architecture","deps":["tech-11.12","tech-11.14"],"refs":["Cardwell"],"tags":["modern","1945"],"pic":"Step a toy von Neumann machine through fetch–decode–execute: program and data share memory, so a program can modify its own instructions."},{"num":"11.16","kind":"Invention","name":"The transistor","deps":["circ-4.11","tech-11.4","mat-9.5"],"refs":["Cardwell"],"tags":["modern","1947"],"pic":"Bias a junction transistor: a small base current controls a large collector current, and size, power and reliability are compared with a triode."},{"num":"11.17","kind":"Invention","name":"The integrated circuit","deps":["tech-11.16"],"refs":["Cardwell"],"tags":["modern","1958–59"],"pic":"Pattern transistors and wires on one chip by photolithography: interconnections no longer need soldering, and yield falls with die area as defects are sprinkled at random."},{"num":"11.18","kind":"Phenomenon","name":"Moore’s law","deps":["tech-11.17"],"refs":["Cardwell"],"tags":["modern","1965"],"pic":"Transistors per chip on a log scale from 1971 onward: fit the doubling time, compare Moore’s 1965 and 1975 forecasts, and see the recent slowdown."},{"num":"11.19","kind":"Invention","name":"The microprocessor","deps":["tech-11.17","tech-11.15"],"refs":["Cardwell"],"tags":["modern","1971"],"pic":"A whole CPU on one chip: execute a short program on a simplified 4-bit processor and watch registers and buses change each cycle."}]},{"n":12,"title":"Lasers, satellites, networks and biotechnology","summary":"The laser and the optical fibre turned light into a carrier of information, satellites put radios in orbit, and GPS turned precise clocks into a positioning system that must correct for relativity. Packet switching made a network robust to failures, and the internet and the web grew on top of it, secured by public-key cryptography. The smartphone combines nearly every earlier strand, and biotechnology turned DNA into something that can be read, copied and edited.","items":[{"num":"12.1","kind":"Invention","name":"The laser","deps":["tech-11.4","qm-13.8"],"refs":["Cardwell"],"tags":["modern","1960"],"pic":"Pump atoms into a population inversion between two mirrors: stimulated emission builds a coherent beam once gain exceeds losses, shown by sliding the pump rate past threshold."},{"num":"12.2","kind":"Invention","name":"Optical fibre communication","deps":["tech-12.1","mech-5.2","waves-4.6"],"refs":["Cardwell"],"tags":["modern","1970"],"pic":"Send light down a fibre: rays beyond the critical angle are trapped by total internal reflection, and attenuation in dB/km falls through the 1970s on a log chart."},{"num":"12.3","kind":"Invention","name":"Artificial satellites and geostationary orbit","deps":["tech-10.7","mech-8.8"],"refs":["Cardwell"],"tags":["modern","1957"],"pic":"Launch to different altitudes: Kepler’s third law gives the period, and at about 35,800 km it matches one sidereal day so the satellite hangs over one point."},{"num":"12.4","kind":"Invention","name":"GPS: positioning by clocks","deps":["tech-12.3","tech-11.9","rel-6.9"],"refs":["Cardwell"],"tags":["modern","1978–95"],"pic":"Intersect spheres of pseudoranges from four satellites to solve for position and receiver clock error; switch off relativistic corrections and the fix drifts about 10 km a day."},{"num":"12.5","kind":"Invention","name":"Packet switching","deps":["tech-11.14"],"refs":["Cardwell"],"tags":["modern","1960s"],"pic":"Break a message into packets that route independently across a mesh: cut links and the packets flow around the damage and reassemble."},{"num":"12.6","kind":"Invention","name":"The internet: ARPANET and TCP/IP","deps":["tech-12.5"],"refs":["Cardwell"],"tags":["modern","1969–83"],"pic":"Send data across connected networks: TCP retransmits lost packets and backs off when congestion appears, shown as the sawtooth of its sending window."},{"num":"12.7","kind":"Invention","name":"Public-key cryptography","deps":["tech-12.6","crypto-9.2"],"refs":["Cardwell"],"tags":["modern","1976–77"],"pic":"Diffie–Hellman with small numbers: two parties exchange public values and arrive at the same secret, while an eavesdropper faces a discrete-logarithm search."},{"num":"12.8","kind":"Invention","name":"The World Wide Web","deps":["tech-12.6"],"refs":["Cardwell"],"tags":["modern","1989–91"],"pic":"Follow hyperlinks between documents on different servers: each click is a URL resolved and fetched by HTTP, drawn as a growing link graph."},{"num":"12.9","kind":"Invention","name":"Cellular networks and frequency reuse","deps":["tech-11.5"],"refs":["Cardwell"],"tags":["modern","1979"],"pic":"Tile a city with hexagonal cells and assign channel sets: interference between co-channel cells depends on the reuse distance, and capacity grows as cells shrink."},{"num":"12.10","kind":"Invention","name":"The silicon solar cell","deps":["tech-11.16","cm-4.7"],"refs":["Cardwell"],"tags":["modern","1954"],"pic":"Shine light on a p–n junction: the I–V curve shifts down, and the maximum-power point and efficiency are read out as irradiance changes."},{"num":"12.11","kind":"Invention","name":"The lithium-ion battery","deps":["tech-9.2"],"refs":["Cardwell"],"tags":["modern","1991"],"pic":"Shuttle lithium ions between graphite and an oxide cathode during charge and discharge: energy per kilogram is compared with lead–acid and nickel cells."},{"num":"12.12","kind":"Invention","name":"The smartphone","deps":["tech-11.19","tech-12.9","tech-12.4","tech-12.8","tech-12.11"],"refs":["Cardwell"],"tags":["modern","c. 2007"],"pic":"Explode a phone into its components and trace each back through the tree: radio, transistor, battery, GPS, the web — an interactive dependency fan."},{"num":"12.13","kind":"Invention","name":"PCR and DNA sequencing","deps":["tech-10.13"],"refs":["Cardwell"],"tags":["modern","1977–83"],"pic":"Cycle temperature to double a DNA segment each round: copies grow as 2ⁿ until reagents run out, and cost per genome falls on a log chart."},{"num":"12.14","kind":"Invention","name":"CRISPR–Cas9 genome editing","deps":["tech-12.13"],"refs":["Cardwell"],"tags":["modern","2012"],"pic":"Design a guide RNA against a target sequence next to a PAM motif: Cas9 cuts there, and off-target sites with one or two mismatches are scored."},{"num":"12.15","kind":"Paper","name":"On Distributed Communications Networks","paper":{"authors":"Paul Baran","year":1964,"title":"On Distributed Communications Networks","venue":"IEEE Transactions on Communications Systems 12 (1): 1–9","doi":"10.1109/TCOM.1964.1088883"},"introduces":["tech-12.5"],"deps":["tech-9.4"],"refs":[],"pic":"Baran’s centralized, decentralized and distributed networks: the reader knocks out nodes and links at random or by targeted attack and watches the fraction of surviving nodes that can still reach each other, recovering his result that a distributed mesh with a redundancy of three or four links per node survives heavy damage, while message blocks are routed around the holes."},{"num":"12.16","kind":"Paper","name":"Extra-Terrestrial Relays","paper":{"authors":"Arthur C. Clarke","year":1945,"title":"Extra-Terrestrial Relays: Can Rocket Stations Give World-wide Radio Coverage?","venue":"Wireless World 51 (10): 305–308","url":"https://web.archive.org/web/20231119064052/http://clarkeinstitute.org/wp-content/uploads/2010/04/ClarkeWirelessWorldArticle.pdf"},"introduces":["tech-12.3"],"deps":["aero-9.16"],"refs":[],"pic":"Clarke’s three stations: the reader drags a relay’s orbit radius until its period is one day (about 42,000 km from Earth’s centre), sees each station’s coverage cap and the signal delay, and spaces three stations 120° apart so that between them they cover the whole inhabited Earth."}]}]};
const items=[...a.items,...b.items],close=(a,b,t=3e-11)=>assert.ok(Math.abs(a-b)<=t*Math.max(1,Math.abs(a),Math.abs(b)),`${a} != ${b}`),rel=(a,b,t=3e-11)=>assert.ok(a===b||Math.abs((a-b)/b)<=t,`${a} != ${b}`),sum=a=>a.reduce((s,x)=>s+x,0),multiply=(A,B)=>A.map(r=>B[0].map((_,j)=>sum(r.map((x,k)=>x*B[k][j]))));
test('all twelve frozen identities, full Paper/introduces and non6 metadata survive',()=>{assert.deepEqual({...sy,chapters:sy.chapters.filter(c=>c.n!==6)},{...BASELINE,chapters:BASELINE.chapters.filter(c=>c.n!==6)});const old=BASELINE.chapters.find(c=>c.n===6),now=sy.chapters.find(c=>c.n===6);assert.equal(items.length,12);assert.deepEqual(items.map(({num,kind,name})=>({num,kind,name})),old.items.map(({num,kind,name})=>({num,kind,name})));assert.deepEqual(items.map(({num,kind,name})=>({num,kind,name})),now.items.map(({num,kind,name})=>({num,kind,name})));for(const key of['paper','introduces']){assert.deepEqual(items[11][key],old.items[11][key]);assert.deepEqual(now.items[11][key],old.items[11][key]);}for(let j=0;j<12;j++){for(const k of['deps','see','paper','introduces','verify','refs'])assert.deepEqual(now.items[j][k],items[j][k]);assert.equal(now.items[j].pic,items[j].caption);}assert.ok(!items.some(i=>i.deps?.includes('ling-7.4')));assert.ok(items[3].see.includes('ling-7.4'));assert.equal(items[11].verify,true);});
test('reduced-eye ray matrix and stable power difference give the geometric blur',()=>{for(const distance of[.2,.3,.4])for(const near of[.4,.7,2])for(const power of[0,1.37,6]){const q=H.spectacles({distance,near,power,aperture:3});for(const y of[-3,0,3]){const incoming=y/distance/1000,outgoing=incoming-(q.eye+power)*y/1000,retina=y+q.L/q.ni*outgoing*1000;close(q.ray(y),retina);close(q.blur,Math.abs(q.ray(3)));}const target=(near-distance)/(near*distance);assert.equal(H.spectacles({distance,near,power:target}).blur,0);}assert.ok(H.spectacles({distance:.4,near:.4,power:Number.MIN_VALUE}).residual<0);});
test('binary relief reverses contact, validates dense shape and declared break-even',()=>{for(let bits=0;bits<64;bits++){const rows=Array.from({length:2},(_,j)=>Array.from({length:3},(_,i)=>(bits>>(3*j+i))&1));assert.deepEqual(H.relief(rows,true).printed,rows);assert.deepEqual(H.relief(rows,false).printed,rows.map(r=>r.slice().reverse()));assert.equal(H.relief(rows).ink,sum(rows.flat()));}const q=H.blockCosts({copies:40,cells:20,carve:2});assert.equal(q.print,80);assert.equal(q.hand,800);close(q.setup+q.breakEven,q.breakEven*20);for(const x of['[]','[[1],[0,1]]','[[2]]','null'])assert.ok(H.parseStencil(x).error);const sparse=Array(2);sparse.foo=[0,0];assert.throws(()=>H.relief(sparse));const r=[Array(1)];r[0].foo=1;assert.throws(()=>H.relief(r));});
test('reusable physical sorts are exact per-character maximum multiplicities',()=>{for(const s of['ABBA|BACA|AAC','字字文|文字|字','|','AAAA|B','😀😀A|😀B']){const q=H.typesetting(s),forms=s.split('|').map(x=>Array.from(x).filter(c=>![' ','\n','\t'].includes(c))),chars=[...new Set(forms.flat())],expected=sum(chars.map(c=>Math.max(...forms.map(f=>f.filter(x=>x===c).length))));assert.equal(q.stock,expected);assert.equal(q.total,sum(forms.map(x=>x.length)));assert.ok(q.stock>=q.classes);assert.ok(q.total>=q.stock);}assert.ok(H.typesetting('x'.repeat(49)).error);assert.ok(H.typesetting('a|b|c|d').error);});
test('press intervals respect independent resources and exact queue recurrence',()=>{for(const forms of[1,5,12])for(const rate of[.5,4.7,20])for(const compose of[1,12,30]){const q=H.pressQueue({forms,rate,compose,copies:31,setup:2.4});let previous=0;for(const row of q.rows){assert.ok(row.start>=row.ready&&row.start>=previous);close(row.end-row.start,2.4+31/rate);assert.equal(row.start,Math.max(row.ready,previous));previous=row.end;}assert.equal(q.end,previous);assert.equal(q.impressions,31*forms);assert.ok(q.end>=q.composerBusy&&q.end>=q.pressBusy);}});
test('catalog cutoff treats the actual Bible date interval without fabricated observations',()=>{assert.equal(H.PRINT_WITNESSES.length,6);for(const y of[1450,1454,1455,1456,1484,1906,1910]){const q=H.witnesses(y);assert.ok(q.definite.length<=q.possible.length);for(const r of q.definite)assert.ok(r.hi<=y);for(const r of q.possible)assert.ok(r.lo<=y);}assert.equal(H.witnesses(1455).definite.length,0);assert.equal(H.witnesses(1455).possible.length,1);assert.equal(H.witnesses(1456).definite.length,1);});
test('signed telescope matrices match independent multiplication and afocal signs',()=>{for(const design of['Galilean','Keplerian'])for(const fo of[.4,.731,1.2])for(const eyepiece of[.03,.071,.1])for(const offset of[-.03,0,.021]){const q=H.telescope({design,fo,eyepiece,offset}),L=f=>[[1,0],[-1/f,1]],M=multiply(L(q.fe),multiply([[1,q.L],[0,1]],L(fo)));close(q.A,M[0][0]);close(q.B,M[0][1]);close(q.C,M[1][0]);close(q.D,M[1][1]);close(q.A*q.D-q.B*q.C,1);for(const y of[-.01,.003,.01]){const r=q.ray(y,.0004);close(r.eyeHeight,y+q.L*(.0004-y/fo));close(r.outSlope,.0004-y/fo-r.eyeHeight/q.fe);}if(offset===0){assert.equal(q.C,0);assert.equal(Math.sign(q.magnification),design==='Galilean'?1:-1);}}for(const offset of[-Number.MIN_VALUE,Number.MIN_VALUE]){const q=H.telescope({offset});assert.equal(q.afocal,false);assert.notEqual(q.C,0);}});
test('Bessel integral, Airy center/first-zero and separation versus magnification',()=>{close(H.j1(1),.4400505857449335,2e-13);close(H.j1(5),-.3275791375914652,2e-13);close(H.j1(50),-.09751182812517514,2e-13);assert.equal(H.airy(0),1);assert.equal(H.airy(Number.MIN_VALUE),1);assert.ok(H.airy(3.8317059702075125)<1e-27);for(const u of[.1,1,3,10])close(H.airy(-u),H.airy(u));const a=H.microscope(),b=H.microscope({singleF:5,objectiveF:10,tube:100});assert.equal(a.rayleigh,b.rayleigh);assert.notEqual(a.compoundM,b.compoundM);const z=H.microscope({separation:0});for(const[x,y]of z.samples)close(y,2*H.airy(2*Math.PI*z.na*x/z.lambda));});
test('actual modern dispersion data give two-line cancellation, not all-line equality',()=>{close(H.index('crown',.5876),1.5168,1e-5);close(H.index('flint',.5876),1.62005,1e-5);for(const power of[1,2.37,5]){const q=H.achromat({power});close(q.lines[0].power,q.lines[2].power,2e-13);close(q.lines[1].power,power,2e-13);assert.ok(q.spread>0);assert.ok(q.k1>0&&q.k2<0);const m=H.achromat({power,mode:'mirror'});assert.equal(m.spread,0);assert.ok(H.achromat({power,mode:'identical glasses'}).singular);assert.ok(H.achromat({power,mode:'single'}).spread>q.spread);}});
test('nonreacting isotherm and work obey PV and exact logarithmic ratios',()=>{for(const amount of[.001,.01,.02])for(const temperature of[250,331,400])for(const volume of[.5,1,4]){const q=H.gas({amount,temperature,volume});close(q.P*volume/1000,amount*8.31446261815324*temperature);close(q.work,amount*8.31446261815324*temperature*Math.log(volume));for(const[V,P]of q.curve)close(P*V,q.P*volume);if(volume===1)assert.equal(q.work,0);}});
test('two-cart impulse and conserved energy are actual solved states including tiny energy',()=>{for(const leftMass of[.2,1,5])for(const rightMass of[.2,2,5])for(const energy of[0,Number.MIN_VALUE,1e-200,.2,1]){const q=H.recoil({leftMass,rightMass,energy,time:2});close(leftMass*q.left+rightMass*q.right,0);close(q.EkL+q.EkR,energy);if(energy>0){assert.ok(q.p>0);rel(q.leftX/q.rightX,-rightMass/leftMass);if(energy>1e-300)rel(.5*leftMass*q.left*q.left+.5*rightMass*q.right*q.right,energy,2e-12);else{assert.ok(q.quantizedEnergy);assert.ok(Math.abs(q.EkL+q.EkR-energy)<=Number.MIN_VALUE);}}else assert.equal(q.p,0);}});
test('finite hydrostatic column and pump recurrence include zero and tiny-ratio branches',()=>{for(const ambient of[0,50000,101325,120000])for(const tube of[.2,.75,1.2]){const q=H.vacuum({ambient,tube});assert.equal(q.h,Math.min(tube,ambient/(q.rho*q.g)));if(q.filled){assert.equal(q.h,tube);assert.ok(q.top>0);}else assert.equal(q.top,0);}for(const ratio of[0,.2,2])for(const leak of[0,.2]){const q=H.vacuum({ratio,leak,strokes:20}),A=(1-leak)/(1+ratio),B=(1-leak)*ratio/(1+ratio)*101325;let p=101325;for(const row of q.rows.slice(1)){p=(1-leak)*p/(1+ratio)+leak*101325;close(row.pressure,p);close(row.deficit,B*sum(Array.from({length:row.stroke},(_,j)=>A**j)));}close(q.force,q.deficit*Math.PI*.1*.1);}const tiny=H.vacuum({ratio:Number.MIN_VALUE,leak:0,strokes:1});assert.ok(tiny.deficit>0);assert.equal(tiny.pressure,tiny.ambient);assert.equal(H.vacuum({ratio:0}).deficit,0);});
test('copy lineages are reproducible actual grids and common error differs from divergence',()=>{const a=H.copying({seed:53,generations:4}),b=H.copying({seed:53,generations:4});assert.deepEqual(a,b);for(const r of a.rows){assert.equal(r.printDivergence,0);for(const p of r.printed)assert.deepEqual(p,r.master);const err=r.hand.flatMap(p=>p.map((x,j)=>+(x!==a.reference[j])));assert.equal(r.handError,sum(err)/(12*48));}const fixed=H.copying({mutation:0,correction:0});fixed.rows.forEach(r=>{assert.equal(r.handError,0);assert.equal(r.handDivergence,0);assert.equal(r.printError,fixed.rows[0].printError);});const repaired=H.copying({masterError:.3,correction:1});assert.equal(repaired.rows[1].printError,0);});
test('declared integer/raw domains reject malformed state parameters',()=>{for(const f of[()=>H.pressQueue({forms:1.5}),()=>H.blockCosts({copies:.5}),()=>H.witnesses(1500.5),()=>H.vacuum({strokes:.5}),()=>H.copying({seed:0}),()=>H.copying({copies:2.5}),()=>H.telescope({design:'unknown'}),()=>H.microscope({naSingle:0}),()=>H.achromat({power:0}),()=>H.gas({volume:0}),()=>H.recoil({energy:-1})])assert.throws(f);});

test('pump sums original positive stroke contributions before subnormal rounding',()=>{const q=H.vacuum({ambient:Number.MIN_VALUE,ratio:.2,leak:0,strokes:20});assert.equal(q.deficit,Number.MIN_VALUE);assert.equal(q.underflow,false);assert.equal(q.rows[1].deficit,0);assert.equal(q.force,0);});

test('near-vacuum pressure is computed independently of its rounded deficit',()=>{const q=H.vacuum({ratio:2,leak:0,strokes:40});assert.ok(q.pressure>0);rel(q.pressure,101325/3**40);assert.equal(q.deficit,q.ambient);assert.equal(H.vacuum({ambient:0}).pressureUnderflow,false);assert.equal(H.vacuum({ambient:Number.MIN_VALUE,ratio:2,leak:0,strokes:40}).pressureUnderflow,true);});

test('catalog qualifications and unavailable place are preserved without invented dating intervals',()=>{const missal=H.PRINT_WITNESSES[1],matisse=H.PRINT_WITNESSES[5];assert.equal(missal.approximate,true);assert.equal(missal.lo,1484);assert.equal(missal.hi,1484);assert.equal(matisse.place,'place not stated in this record');assert.match(items[4].idea,/nominal counting year/);});

test('tiny pump pressure uses exact original-rational nearest-even rounding',()=>{for(const [ratio,leak]of[[1,.2],[1,Number.MIN_VALUE],[1-Number.EPSILON/2,0]]){const q=H.vacuum({ambient:Number.MIN_VALUE,ratio,leak,strokes:1});assert.equal(q.pressure,Number.MIN_VALUE);assert.equal(q.pressureUnderflow,false);}const q=H.vacuum({ambient:Number.MIN_VALUE,ratio:2,leak:0,strokes:40});assert.equal(q.deficit,Number.MIN_VALUE);assert.equal(q.force,0);assert.equal(q.forceUnderflow,true);assert.equal(H.vacuum({ambient:0}).forceUnderflow,false);assert.equal(H.roundFraction(1n,1n<<1075n),0);assert.equal(H.roundFraction(3n,1n<<1075n),2*Number.MIN_VALUE);for(const x of[Number.MIN_VALUE,1e-300,.1,1,1e8])assert.equal(H.roundFraction(...H.binaryFraction(x)),x);});

test('tiny energy uses original mass fractions before denominator rounding',()=>{const q=H.recoil({leftMass:1,rightMass:1-Number.EPSILON/2,energy:Number.MIN_VALUE});assert.equal(q.EkL,0);assert.equal(q.EkR,Number.MIN_VALUE);const r=H.recoil({leftMass:1-Number.EPSILON/2,rightMass:1,energy:Number.MIN_VALUE});assert.equal(r.EkL,Number.MIN_VALUE);assert.equal(r.EkR,0);});
